def ledger(ops: list[str]) -> tuple[dict[str, int], list[int]]:
    balances: dict[str, int] = {}
    frozen: set[str] = set()
    history: list[tuple] = []
    rejected: list[int] = []

    def parse_amount(s: str) -> int | None:
        if s.isascii() and s.isdigit():
            return int(s)
        return None

    for idx, op in enumerate(ops):
        parts = op.split(" ")
        cmd = parts[0]

        if cmd == "open" and len(parts) == 3:
            acc = parts[1]
            amount = parse_amount(parts[2])
            if amount is not None and acc not in balances:
                balances[acc] = amount
                history.append(("open", acc))
            else:
                rejected.append(idx)

        elif cmd == "deposit" and len(parts) == 3:
            acc = parts[1]
            amount = parse_amount(parts[2])
            if amount is not None and amount > 0 and acc in balances:
                balances[acc] += amount
                history.append(("deposit", acc, amount))
            else:
                rejected.append(idx)

        elif cmd == "withdraw" and len(parts) == 3:
            acc = parts[1]
            amount = parse_amount(parts[2])
            if (
                amount is not None
                and amount > 0
                and acc in balances
                and acc not in frozen
                and balances[acc] >= amount
            ):
                balances[acc] -= amount
                history.append(("withdraw", acc, amount))
            else:
                rejected.append(idx)

        elif cmd == "transfer" and len(parts) == 4:
            src, dst = parts[1], parts[2]
            amount = parse_amount(parts[3])
            if (
                amount is not None
                and amount > 0
                and src != dst
                and src in balances
                and dst in balances
                and src not in frozen
                and balances[src] >= amount
            ):
                balances[src] -= amount
                balances[dst] += amount
                history.append(("transfer", src, dst, amount))
            else:
                rejected.append(idx)

        elif cmd == "freeze" and len(parts) == 2:
            acc = parts[1]
            if acc in balances and acc not in frozen:
                frozen.add(acc)
                history.append(("freeze", acc))
            else:
                rejected.append(idx)

        elif cmd == "unfreeze" and len(parts) == 2:
            acc = parts[1]
            if acc in balances and acc in frozen:
                frozen.remove(acc)
                history.append(("unfreeze", acc))
            else:
                rejected.append(idx)

        elif cmd == "undo" and len(parts) == 1:
            if not history:
                rejected.append(idx)
            else:
                action = history.pop()
                kind = action[0]
                if kind == "open":
                    acc = action[1]
                    del balances[acc]
                    frozen.discard(acc)
                elif kind == "deposit":
                    _, acc, amount = action
                    balances[acc] -= amount
                elif kind == "withdraw":
                    _, acc, amount = action
                    balances[acc] += amount
                elif kind == "transfer":
                    _, src, dst, amount = action
                    balances[dst] -= amount
                    balances[src] += amount
                elif kind == "freeze":
                    frozen.remove(action[1])
                elif kind == "unfreeze":
                    frozen.add(action[1])

        else:
            rejected.append(idx)

    return balances, rejected
